import{z as s,x as o,o as e,c as p,q as i,j as n,D as a,d as B,s as l,S as r,b as A}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"日本市场","description":"","frontmatter":{"title":"日本市场","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/gm-japan.md","filePath":"quant/gm-japan.md","lastUpdated":1791413859000}'),d={name:"quant/gm-japan.md"};function m(D,E,C,u,F,h){const t=o("Mermaid");return e(),p("div",null,[E[2]||(E[2]=i('<h1 id="日本市场" tabindex="-1">日本市场 <a class="header-anchor" href="#日本市场" aria-label="Permalink to &quot;日本市场&quot;">​</a></h1><div class="epigraph"><p>日本把撮合引擎推到全球最快的一档，又把午间休市、单元股和每日价格带这些老制度原样保留——现代吞吐量与旧参数表住在同一张订单里，迁移策略要同时读两半。</p><footer>—— 据 JPX / 东京证券交易所公开交易规则与 J-GATE 技术资料整理</footer></div><p><a href="/quant/gm-eu-mifid">上一课</a>写欧洲如何用义务与豁免代替机械保护。日本是另一个方向：几乎没有欧美式的场所碎片化问题——东京证券交易所一家独大，多场所竞争被压到极小——它的难点是把最现代的撮合基础设施与最老的一组制度残余放进同一张参数表。本课写东证的会话、引擎、价格带与卖空约束，沿用前两课的清单口径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>在日本落地策略，缺口集中在四个被别处视为「已解决」的假设上。其一，连续性：现货交易分午前与午后两段，中间有午间休市——日内季节性、隔午的量价关系、休市前后的库存处理都按两段重组，把「全天连续」写死的日内模型在午休边界直接失真。其二，股数：单元股制度下多数品种按整手交易，不足单元走券商柜台的风险较少（risk-less principal）撮合——高价股的最小参与金额被整手放大，规模分层与再平衡精度都要按整手重排。其三，价格带：値幅制（每日价格限制）至今在用，价格贴带时的可成交性与发现延迟与涨跌停市场同族。其四，引擎与历史数据：撮合已统一到 J-GATE 家族——衍生品先迁移、现货后迁——吞吐与撮合语义一起换掉，迁移日前后的微观结构统计不可直接混用。</p><p><span class="marginnote">「单元股」给个数字感觉：一只股价 8000 日元的股票若按 100 股一手，最小买一手就是 80 万日元（约几万人民币）；美股同价位可以买 1 股。组合优化若要配 0.3% 的目标权重，可能凑不齐一手，只能取整到 0.5% 或 0——这就是「再平衡颗粒度被整手放大」的含义，不足一手的部分则由券商柜台风险较少地撮合。</span></p><p><span class="marginnote">引擎迁移把撮合语义与容量一起更换：以迁移日为断点切样本是硬要求；把迁移前测出的撤单率、队列衰减参数直接搬进迁移后，是日本数据里最常见的静默错误。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>清单法继续，按参数表逐项核对。会话与时钟：按两段会话重写日内季节性与尾盘逻辑，休市时长作为参数入表。tick：按价格带查表，高价股与低价股的价距不同，报价逻辑要按档位切换。价格带：值幅制的带值按品种与价格档给出，贴带邻近状态进入特征与风控——磁吸与延迟发现的实证传统来自东京市场本身（Kim and Rhee, 1997），与 A 股涨跌停的邻近效应同一族逻辑，处理方式可参照<a href="/quant/cn-limit-proximity">涨跌停邻近效应</a>。卖空：有不得低于最新成交价的卖空价格约束与交付义务，借券可得性决定可执行集。数据侧：东证官方统计、PTS（私设交易系统）份额的口径差异要分开报告，自建包络与官方口径不可混。</p><p><span class="marginnote">「値幅制」可以类比成游乐园的身高线：每天开盘前按昨收价算出一条「今日允许的价格走廊」，价格走到走廊边缘就进不去更远的区间。它和涨跌停的区别是走廊按价格档分档给出（贵一点的股票带宽比例更窄），且具体带值是查表得到的制度参数，不是统一的 10%。</span></p>',10)),(e(),n(r,null,{default:a(()=>[l(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20AM%5B%22%E5%8D%88%E5%89%8D%E4%BC%9A%E8%AF%9D%22%5D%20--%3E%20LUNCH%5B%22%E5%8D%88%E9%97%B4%E4%BC%91%E5%B8%82%22%5D%0A%20%20LUNCH%20--%3E%20PM%5B%22%E5%8D%88%E5%90%8E%E4%BC%9A%E8%AF%9D%22%5D%0A%20%20AM%20--%3E%20EG%5B%22J-GATE%20%E6%92%AE%E5%90%88%22%5D%0A%20%20PM%20--%3E%20EG%0A%20%20EG%20--%3E%20BAND%5B%22%E5%80%A4%E5%B9%85%E5%88%B6%EF%BC%9A%E6%AF%8F%E6%97%A5%E4%BB%B7%E6%A0%BC%E5%B8%A6%22%5D%0A%20%20EG%20--%3E%20UNIT%5B%22%E5%8D%95%E5%85%83%E8%82%A1%E4%B8%8E%E7%AB%AF%E8%82%A1%E6%9F%9C%E5%8F%B0%22%5D%0A%20%20BAND%20--%3E%20PROX%5B%22%E8%B4%B4%E5%B8%A6%EF%BC%9A%E7%A3%81%E5%90%B8%E4%B8%8E%E5%BB%B6%E8%BF%9F%E5%8F%91%E7%8E%B0%22%5D%0A%20%20UNIT%20--%3E%20LOT%5B%22%E6%95%B4%E6%89%8B%E7%BA%A6%E6%9D%9F%EF%BC%9A%E8%A7%84%E6%A8%A1%E5%88%86%E5%B1%82%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[B("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"四个约束的机制各管一段。午休把「隔夜效应」切成「隔夜」与「隔午」两类：隔午的不确定性远小于隔夜，持有决策的持仓费要分窗计算；混为一个隔夜项会把波动预测的日历写错。整手约束把最小调整量变成价格的函数，高价股的再平衡颗粒度变粗，组合优化的换手成本要加一层取整损失。値幅制作为硬边界截断发现过程：贴带时均衡价可能在带外，次日重开继续走——把带内收盘当均衡价，回测会把配给当成交。J-GATE 的机制意义是场内竞争转向延迟与 PTS：交易所内撮合足够快之后，竞争转移到接入质量与场外系统，份额统计要跟着走。",-1)),E[5]||(E[5]=A("p",null,"一天的持仓风险在东京该怎么分窗——隔午与隔夜的不确定性量级不同，这条分窗图回答的是「持仓费为什么要按窗口分别计」：",-1)),(e(),n(r,null,{default:a(()=>[l(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Hold%5B%22%E6%8C%81%E4%BB%93%E8%B7%A8%E8%BF%87%E4%B8%A4%E4%B8%AA%E5%81%9C%E5%B8%82%E7%AA%97%22%5D%20--%3E%20W1%7B%22%E8%B7%A8%E7%9A%84%E6%98%AF%E5%93%AA%E4%B8%AA%E7%AA%97%22%7D%0A%20%20W1%20--%20%22%E5%8D%88%E9%97%B4%E4%BC%91%E5%B8%82%20%E7%BA%A61%E5%B0%8F%E6%97%B6%22%20--%3E%20Lunch%5B%22%E9%9A%94%E5%8D%88%EF%BC%9A%E4%BF%A1%E6%81%AF%E9%87%8F%E5%B0%8F%20%E6%B3%A2%E5%8A%A8%E5%B0%8F%22%5D%0A%20%20W1%20--%20%22%E9%9A%94%E5%A4%9C%20%E6%94%B6%E7%9B%98%E5%88%B0%E6%AC%A1%E6%97%A5%E5%BC%80%E7%9B%98%22%20--%3E%20Night%5B%22%E9%9A%94%E5%A4%9C%EF%BC%9A%E5%85%A8%E7%90%83%E4%BF%A1%E6%81%AF%E7%B4%AF%E7%A7%AF%20%E9%A3%8E%E9%99%A9%E5%A4%A7%22%5D%0A%20%20Lunch%20--%3E%20Fee1%5B%22%E4%BD%8E%E6%8C%81%E4%BB%93%E8%B4%B9%20%E7%BB%A7%E7%BB%AD%E6%8C%81%E6%9C%89%E6%88%90%E6%9C%AC%E4%BD%8E%22%5D%0A%20%20Night%20--%3E%20Fee2%5B%22%E9%AB%98%E6%8C%81%E4%BB%93%E8%B4%B9%20%E6%8C%89%E9%9A%94%E5%A4%9C%E6%B3%A2%E5%8A%A8%E8%AE%A1%22%5D%0A%20%20Fee1%20--%3E%20Split%5B%22%E5%88%86%E7%AA%97%E8%AE%A1%E8%B4%B9%E8%80%8C%E4%B8%8D%E6%98%AF%E5%8D%95%E4%B8%80%E9%9A%94%E5%A4%9C%E9%A1%B9%22%5D%0A%20%20Fee2%20--%3E%20Split%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=i('<p><span class="marginnote">常见误区：初学者容易把贴带日的收盘价当「市场最终意见」。实际上値幅制贴带时，真实均衡价很可能在带外，买卖被制度配给了——收盘价只是「带内能成交的价格」。把配给当成交写进回测，策略在贴带日的绩效会系统性失真。</span></p><p>不这么做会错在哪：把美国式「连续、碎股、无价格带」的假设整体搬进日本，四个假设同时失效而表面指标正常——最危险的一类迁移错误。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写日股的因子与公司治理专题，不写 PTS 的内部撮合细节。带值、时段与整手的具体参数以 JPX 当期规则为准——这套制度处于渐进改革中（整手品种逐步放开、时段延长），清单必须带日期重读。结算周期与后链放到清算结算课统一对照。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>日本的对象是「快引擎加旧参数表」：午休、整手、値幅制与 J-GATE 共存。</li><li>日内结构按两段会话重写，隔夜与隔午分开计持仓费。</li><li>值幅制贴带状态是特征与风控项，带内收盘不等于均衡价。</li><li>卖空受价格约束与交付义务限制，可执行集由借券可得性决定。</li><li>引擎迁移日是硬断点，迁移前的微观结构参数不得静默沿用。</li><li>出处：JPX / 东证公开交易规则与 J-GATE 资料；Kim and Rhee, <em>Journal of Finance</em>, 1997（东京价格限制与价格发现）。</li></ul>',6))])}const f=s(d,[["render",m]]);export{c as __pageData,f as default};
